  function generateFastenNonce(userId: string): string {
    const nonce = randomBytes(32).toString("hex");
    const expiresAt = Date.now() + 15 * 60 * 1000;
    fastenConnectNonces.set(nonce, { userId, expiresAt });
    pruneExpiredFastenEntries();
    return nonce;
  }


  function validateFastenNonce(nonce: string, userId: string, orgConnectionId?: string): boolean {
    const entry = fastenConnectNonces.get(nonce);
    if (!entry) return false;
    if (entry.userId !== userId) return false;
    if (Date.now() > entry.expiresAt) {
      fastenConnectNonces.delete(nonce);
      return false;
    }
    if (orgConnectionId) {
      if (entry.boundOrgConnectionId && entry.boundOrgConnectionId !== orgConnectionId) {
        return false;
      }
      if (!entry.boundOrgConnectionId) {
        entry.boundOrgConnectionId = orgConnectionId;
      }
    }
    return true;
  }


  function consumeFastenNonce(nonce: string): void {
    fastenConnectNonces.delete(nonce);
  }


