  async function processSyncJob(jobId: string, source: any, direction: string) {
    try {
      await storage.updateFhirSyncJob(jobId, { status: "connecting", phase: "authentication" });
      
      const config = await storage.getFhirConnectionConfig(source.id);
      const headers: Record<string, string> = { "Accept": "application/fhir+json" };
      
      // Load custom mapping rules for this connection
      const connectionMappingRules = await storage.getMappingRulesForConnection(source.userId, source.id);
      const globalMappingRules = await storage.getMappingRulesForConnection(source.userId, null);
      const allMappingRules = [...connectionMappingRules, ...globalMappingRules].filter(r => r.isActive);
      const codeMappings = await storage.getAllCodeMappings(source.userId);
      
      if (config?.authType === "bearer" && source.accessToken) {
        headers["Authorization"] = `Bearer ${source.accessToken}`;
      } else if (config?.authType === "basic" && source.accessToken) {
        headers["Authorization"] = `Basic ${source.accessToken}`;
      }
      
      await storage.updateFhirSyncJob(jobId, { phase: "discovery" });
      
      // Get supported resources from server and user-configured resource types
      const supportedResources = config?.supportedResources as any[] || [];
      const serverResourceTypes = supportedResources.map((r: any) => r.type);
      
      // Get user-configured enabled resource types for this source
      const enabledResourceTypes = await storage.getEnabledResourceTypes(source.id);
      
      // If user has configured resource types, use them; otherwise use defaults
      const defaultResourceTypes = ["Patient", "Observation", "Condition", "MedicationRequest", "MedicationStatement", "Medication", "Procedure", "Immunization", "AllergyIntolerance", "Encounter", "DiagnosticReport"];
      const targetResourceTypes = enabledResourceTypes.length > 0 ? enabledResourceTypes : defaultResourceTypes;
      
      // Filter to only resources supported by both server and user configuration
      const resourcesToSync = serverResourceTypes.length > 0
        ? targetResourceTypes.filter((r: string) => serverResourceTypes.includes(r))
        : targetResourceTypes;
      
      await storage.updateFhirSyncJob(jobId, { 
        phase: "fetching",
        status: "syncing",
        resourceTypes: resourcesToSync,
        totalResources: resourcesToSync.length * 10, // Estimate
      });
      
      const syncSinkValidation = await tryValidateExternalUrl(source.fhirEndpoint || "");
      if (!syncSinkValidation.valid) {
        await storage.updateFhirSyncJob(jobId, {
          status: "failed",
          completedAt: new Date(),
          errors: [{ code: "invalid_endpoint", message: `FHIR endpoint is not reachable from this server: ${syncSinkValidation.error}` }],
        });
        return;
      }

      let processedCount = 0;
      let importedCount = 0;
      let failedCount = 0;
      const errors: any[] = [];
      
      for (const resourceType of resourcesToSync) {
        try {
          // Check if job was cancelled
          const currentJob = await storage.getFhirSyncJob(jobId);
          if (currentJob?.status === "cancelled") {
            return;
          }
          
          await storage.updateFhirSyncJob(jobId, { lastResourceType: resourceType });
          
          // Fetch resources
          const searchUrl = source.patientId 
            ? `${source.fhirEndpoint}/${resourceType}?patient=${source.patientId}&_count=100`
            : `${source.fhirEndpoint}/${resourceType}?_count=100`;
          
          const response = await safeFetch(searchUrl, { headers, signal: AbortSignal.timeout(60000) });
          
          if (!response.ok) {
            errors.push({ resourceType, error: `HTTP ${response.status}`, timestamp: new Date().toISOString() });
            failedCount++;
            continue;
          }
          
          const bundle = await response.json();
          const entries = bundle.entry || [];
          
          for (const entry of entries) {
            try {
              const resource = entry.resource;
              if (!resource) continue;
              
              // Find applicable mapping rules for this resource type
              const applicableRules = allMappingRules
                .filter(r => r.fhirResourceType === resource.resourceType)
                .sort((a, b) => (b.priority || 0) - (a.priority || 0));
              
              // Map FHIR resource to health record, applying custom mappings
              const record = mapFhirResourceToRecord(resource, source.userId, source.id, applicableRules, codeMappings);
              if (record) {
                // Check for existing record
                const existingRecords = await storage.getHealthRecordsByFhirId(source.userId, resource.resourceType, resource.id);
                
                if (existingRecords.length > 0) {
                  await storage.updateHealthRecord(existingRecords[0].id, { ...record, lastSyncedAt: new Date() });
                } else {
                  await storage.createHealthRecord(record);
                }
                importedCount++;
              }
              processedCount++;
            } catch (recordError: any) {
              errors.push({ resourceType, error: recordError.message, timestamp: new Date().toISOString() });
              failedCount++;
            }
          }
          
          await storage.updateFhirSyncJob(jobId, { 
            processedResources: processedCount,
            importedResources: importedCount,
            failedResources: failedCount,
            progressPercentage: Math.round((resourcesToSync.indexOf(resourceType) + 1) / resourcesToSync.length * 100),
          });
        } catch (resourceError: any) {
          errors.push({ resourceType, error: resourceError.message, timestamp: new Date().toISOString() });
          failedCount++;
        }
      }
      
      await storage.updateFhirSyncJob(jobId, {
        status: "completed",
        phase: "finalizing",
        processedResources: processedCount,
        importedResources: importedCount,
        failedResources: failedCount,
        errors: errors.length > 0 ? errors : null,
        progressPercentage: 100,
        completedAt: new Date(),
      });
      
      await storage.updateDataSource(source.id, {
        lastSyncAt: new Date(),
        recordCount: (source.recordCount || 0) + importedCount,
      });
    } catch (error: any) {
      await storage.updateFhirSyncJob(jobId, {
        status: "failed",
        errors: [{ message: error.message, timestamp: new Date().toISOString() }],
        completedAt: new Date(),
      });
    }
  }


  function mapFhirResourceToRecord(resource: any, userId: string, sourceId: string, customRules: any[] = [], codeMappings: any[] = []): any {
    const typeMapping: Record<string, string> = {
      // Clinical resources
      Observation: "labs",
      Condition: "condition",
      Procedure: "procedure",
      Immunization: "immunization",
      AllergyIntolerance: "allergy",
      FamilyMemberHistory: "condition",
      RiskAssessment: "labs",
      ClinicalImpression: "visit",
      
      // Medication resources
      MedicationRequest: "medication",
      Medication: "medication",
      MedicationStatement: "medication",
      MedicationDispense: "medication",
      MedicationAdministration: "medication",
      
      // Administrative resources
      Encounter: "visit",
      Patient: "other",
      Practitioner: "other",
      Organization: "other",
      CareTeam: "other",
      
      // Diagnostic resources
      DiagnosticReport: "labs",
      ImagingStudy: "imaging",
      Media: "imaging",
      Specimen: "labs",
      
      // Document resources
      DocumentReference: "other",
      Composition: "other",
      
      // Care planning resources
      CarePlan: "other",
      Goal: "other",
      ServiceRequest: "procedure",
      
      // Financial resources
      Coverage: "other",
      Claim: "other",
      ExplanationOfBenefit: "other",
      
      // Privacy resources
      Consent: "other",
      
      // Assessment resources
      QuestionnaireResponse: "other",
      
      // Device resources
      DeviceUseStatement: "other",
      Device: "other",
    };
    
    // Start with default mapping
    let recordType = typeMapping[resource.resourceType] || "other";
    let record: any = {
      userId,
      sourceId,
      type: recordType,
      title: extractTitle(resource),
      summary: extractSummary(resource),
      date: extractDate(resource),
      provider: extractProvider(resource),
      facility: null,
      fhirResourceType: resource.resourceType,
      fhirResourceId: resource.id,
      rawFhirJson: resource,
      isManual: false,
      details: extractDetails(resource),
    };
    
    // Apply custom mapping rules
    for (const rule of customRules) {
      // Check if rule conditions match
      if (!evaluateMappingConditions(resource, rule.conditions)) continue;
      
      // Apply target record type if specified
      if (rule.internalRecordType) {
        record.type = rule.internalRecordType;
      }
      
      // Apply field mappings
      const fieldMappings = rule.fieldMappings as any[];
      if (fieldMappings && Array.isArray(fieldMappings)) {
        for (const mapping of fieldMappings) {
          const sourceValue = getNestedValueFromPath(resource, mapping.sourcePath);
          if (sourceValue !== undefined) {
            const transformedValue = applyFieldTransformation(sourceValue, mapping, codeMappings);
            setNestedValue(record, mapping.targetField, transformedValue);
          }
        }
      }
    }
    
    return record;
  }

  
  function evaluateMappingConditions(resource: any, conditions: any): boolean {
    if (!conditions) return true;
    
    const conditionsArray = Array.isArray(conditions) ? conditions : [conditions];
    for (const condition of conditionsArray) {
      if (!condition.field || !condition.operator) continue;
      
      const fieldValue = getNestedValueFromPath(resource, condition.field);
      
      switch (condition.operator) {
        case "equals":
          if (fieldValue !== condition.value) return false;
          break;
        case "not_equals":
          if (fieldValue === condition.value) return false;
          break;
        case "contains":
          if (typeof fieldValue !== "string" || !fieldValue.includes(condition.value)) return false;
          break;
        case "exists":
          if (fieldValue === undefined || fieldValue === null) return false;
          break;
        case "not_exists":
          if (fieldValue !== undefined && fieldValue !== null) return false;
          break;
        case "in":
          if (!Array.isArray(condition.value) || !condition.value.includes(fieldValue)) return false;
          break;
        case "starts_with":
          if (typeof fieldValue !== "string" || !fieldValue.startsWith(condition.value)) return false;
          break;
      }
    }
    return true;
  }

  
  function getNestedValueFromPath(obj: any, path: string): any {
    if (!path || !obj) return undefined;
    
    const parts = path.split(".");
    let current = obj;
    
    for (const part of parts) {
      // Handle array notation like "coding[0]"
      const arrayMatch = part.match(/^(\w+)\[(\d+)\]$/);
      if (arrayMatch) {
        current = current?.[arrayMatch[1]]?.[parseInt(arrayMatch[2])];
      } else {
        current = current?.[part];
      }
      
      if (current === undefined) return undefined;
    }
    
    return current;
  }

  
  function setNestedValue(obj: any, path: string, value: any): void {
    if (!path) return;
    
    const parts = path.split(".");
    let current = obj;
    
    for (let i = 0; i < parts.length - 1; i++) {
      if (!current[parts[i]]) current[parts[i]] = {};
      current = current[parts[i]];
    }
    
    current[parts[parts.length - 1]] = value;
  }

  
  function applyFieldTransformation(value: any, mapping: any, codeMappings: any[]): any {
    const transform = mapping.transformation;
    if (!transform) return value;
    
    switch (transform.type) {
      case "format":
        return transform.formatString?.replace("{value}", String(value)) || value;
        
      case "date":
        try {
          const date = new Date(value);
          if (transform.outputFormat === "iso") return date.toISOString();
          if (transform.outputFormat === "date") return date.toISOString().split("T")[0];
          return date.toLocaleDateString();
        } catch { return value; }
        
      case "number":
        const num = parseFloat(value);
        if (isNaN(num)) return value;
        if (transform.precision !== undefined) return num.toFixed(transform.precision);
        if (transform.multiply) return num * transform.multiply;
        return num;
        
      case "concat":
        if (transform.fields && Array.isArray(transform.fields)) {
          return transform.fields.map((f: string) => getNestedValueFromPath(value, f) || "").join(transform.separator || " ");
        }
        return value;
        
      case "lookup":
        const matchingCode = codeMappings.find(cm => 
          cm.sourceSystem === transform.sourceSystem &&
          cm.sourceCode === String(value) &&
          cm.targetSystem === transform.targetSystem
        );
        return matchingCode?.targetDisplay || matchingCode?.targetCode || value;
        
      case "lowercase":
        return String(value).toLowerCase();
        
      case "uppercase":
        return String(value).toUpperCase();
        
      case "trim":
        return String(value).trim();
        
      case "first":
        return Array.isArray(value) ? value[0] : value;
        
      case "join":
        return Array.isArray(value) ? value.join(transform.separator || ", ") : value;
        
      case "regex":
        if (transform.pattern && transform.replacement !== undefined) {
          return String(value).replace(new RegExp(transform.pattern, "g"), transform.replacement);
        }
        return value;
        
      default:
        return value;
    }
  }


  function extractTitle(resource: any): string {
    switch (resource.resourceType) {
      case "Observation":
        return resource.code?.text || resource.code?.coding?.[0]?.display || "Observation";
      case "Condition":
        return resource.code?.text || resource.code?.coding?.[0]?.display || "Condition";
      case "MedicationRequest":
        return resource.medicationCodeableConcept?.text || resource.medicationCodeableConcept?.coding?.[0]?.display || "Medication";
      case "Procedure":
        return resource.code?.text || resource.code?.coding?.[0]?.display || "Procedure";
      case "Immunization":
        return resource.vaccineCode?.text || resource.vaccineCode?.coding?.[0]?.display || "Immunization";
      case "AllergyIntolerance":
        return resource.code?.text || resource.code?.coding?.[0]?.display || "Allergy";
      case "Encounter":
        return resource.type?.[0]?.text || resource.type?.[0]?.coding?.[0]?.display || "Visit";
      default:
        return resource.resourceType;
    }
  }


  function extractSummary(resource: any): string {
    switch (resource.resourceType) {
      case "Observation":
        const value = resource.valueQuantity 
          ? `${resource.valueQuantity.value} ${resource.valueQuantity.unit || ''}`
          : resource.valueString || resource.valueCodeableConcept?.text || '';
        return value || "No value recorded";
      case "Condition":
        return resource.clinicalStatus?.coding?.[0]?.code || "Unknown status";
      case "MedicationRequest":
        return resource.dosageInstruction?.[0]?.text || "See prescription details";
      default:
        return resource.text?.div?.replace(/<[^>]*>/g, '') || "";
    }
  }


  function extractDate(resource: any): Date {
    const dateFields = [
      resource.effectiveDateTime,
      resource.authoredOn,
      resource.recordedDate,
      resource.onsetDateTime,
      resource.occurrenceDateTime,
      resource.period?.start,
      resource.meta?.lastUpdated,
    ];
    
    for (const field of dateFields) {
      if (field) {
        const date = new Date(field);
        if (!isNaN(date.getTime())) return date;
      }
    }
    
    return new Date();
  }


  function extractProvider(resource: any): string | null {
    if (resource.performer?.[0]?.display) return resource.performer[0].display;
    if (resource.recorder?.display) return resource.recorder.display;
    if (resource.asserter?.display) return resource.asserter.display;
    if (resource.requester?.display) return resource.requester.display;
    return null;
  }


  function extractDetails(resource: any): Record<string, any> {
    const details: Record<string, any> = {};
    
    if (resource.valueQuantity) {
      details.value = resource.valueQuantity.value;
      details.unit = resource.valueQuantity.unit;
    }
    if (resource.interpretation) {
      details.interpretation = resource.interpretation[0]?.text || resource.interpretation[0]?.coding?.[0]?.display;
    }
    if (resource.category) {
      details.category = resource.category[0]?.text || resource.category[0]?.coding?.[0]?.display;
    }
    if (resource.status) {
      details.status = resource.status;
    }
    
    return details;
  }

