  function calculateProfileCompleteness(profile: any): number {
    const fields = [
      'firstName', 'lastName', 'dateOfBirth', 'gender', 'phone', 'email',
      'addressLine1', 'city', 'state', 'zipCode', 'emergencyContacts', 'insuranceInfo',
      'bloodType', 'primaryPhysician',
      'sexualOrientation', 'genderIdentity', 'tribalAffiliation', 'insuranceCoverageStatus'
    ];
    
    const filledFields = fields.filter(field => {
      const value = profile[field];
      if (Array.isArray(value)) return value.length > 0;
      return value !== null && value !== undefined && value !== '';
    });
    
    return Math.round((filledFields.length / fields.length) * 100);
  }


