  // Get all health journeys for user


  const smsLog: any[] = [];

  // Per-user rate limit for arbitrary-recipient SMS sends (send + test endpoints).
  // Allows at most SMS_SEND_MAX_PER_WINDOW sends per user within SMS_SEND_WINDOW_MS.

  const SMS_SEND_WINDOW_MS = 60 * 60 * 1000; // 1 hour

  const SMS_SEND_MAX_PER_WINDOW = 10;

  const smsSendRateMap = new Map<string, { count: number; windowStart: number }>();


  function checkSmsSendRateLimit(userId: string): boolean {
    const now = Date.now();
    const entry = smsSendRateMap.get(userId);
    if (!entry || now - entry.windowStart >= SMS_SEND_WINDOW_MS) {
      smsSendRateMap.set(userId, { count: 1, windowStart: now });
      if (smsSendRateMap.size > 20000) {
        const cutoff = now - SMS_SEND_WINDOW_MS;
        for (const [k, v] of smsSendRateMap.entries()) {
          if (v.windowStart < cutoff) smsSendRateMap.delete(k);
        }
      }
      return true;
    }
    if (entry.count >= SMS_SEND_MAX_PER_WINDOW) {
      return false;
    }
    entry.count++;
    return true;
  }

