  function generateDemoExchanges(networkId?: string, limit: number = 50) {
    const networks = ["commonwell", "carequality", "epic-nexus", "ehealth-exchange", "health-gorilla", "konza", "medallies", "surescripts"];
    const purposes = ["treatment", "individual_access", "healthcare_operations", "payment"];
    const types = ["query", "retrieve", "response"] as const;
    const directions = ["inbound", "outbound"] as const;
    const statuses = ["success", "success", "success", "success", "success", "error"] as const;
    const errorCodes = ["TIMEOUT", "AUTH_FAILED", "PATIENT_NOT_FOUND", "RATE_LIMITED", "INVALID_RESPONSE"];

    const exchanges = [];
    for (let i = 0; i < Math.min(limit, 50); i++) {
      const net = networkId || networks[Math.floor(Math.random() * networks.length)];
      const status = statuses[Math.floor(Math.random() * statuses.length)];
      exchanges.push({
        id: `txn_demo_${Date.now()}_${i}`,
        queryId: `q_${Math.random().toString(36).substr(2, 8)}`,
        type: types[Math.floor(Math.random() * types.length)],
        direction: directions[Math.floor(Math.random() * directions.length)],
        networkId: net,
        timestamp: new Date(Date.now() - i * 3600000 - Math.random() * 3600000),
        exchangePurpose: purposes[Math.floor(Math.random() * purposes.length)],
        status,
        errorCode: status === "error" ? errorCodes[Math.floor(Math.random() * errorCodes.length)] : undefined,
        documentCount: Math.floor(Math.random() * 5),
        auditDetails: {
          requesterOrganization: "Tabula Medica",
          consentVerified: true,
        },
      });
    }
    return exchanges.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }

